custom_css:
/* === 溺于蓝 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. === */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Caveat:wght@400;700&display=swap'); /* 优雅英文手写体 */
@import url('https://fonts.googleapis.com/css2?family=Kiwi+Maru:wght@300;400&display=swap'); /* 日系可爱装饰字体 */
@import url("https://fontsapi.zeoseven.com/256/main/result.css"); /* 全局中文: 汇文体 */
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  /* 代码: nzgrRuYinZouZhangKai */
@import url("https://fontsapi.zeoseven.com/521/main/result.css"); /* 引用: JetBrains Maple Mono */
@import url("https://fontsapi.zeoseven.com/7/main/result.css"); /* 标题修改: 朱雀仿宋 */

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg-color: #E6F0FA; /* 冰雪蓝 */
    --theme-bg-mid: #AECBFA; /* 勿忘我蓝 */
    --card-bg: rgba(255, 255, 255, 0.65); /* 琉璃白 */
    --accent-blue: #4A90E2; /* 沉溺深蓝 */
    --accent-coral: #FF9EAA; /* 花火粉红（点缀） */
    --accent-glow: #87CEFA; /* 幽蓝荧光 */
    --text-main: #1C2D42; /* 深渊蓝，高对比度防瞎眼 */
    --text-subtle: #5C7A99; /* 浅海蓝 */

    --font-english: 'Caveat', cursive;
    --font-japanese: 'Kiwi Maru', serif;
    --font-main: "Huiwen-mincho", var(--font-english), sans-serif;
    --font-quote: "JetBrains Maple Mono", var(--font-english), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "Zhuque Fangsong (technical preview)", var(--font-japanese), serif;
}

/* --- 3. 全局样式与无阴影无边框设定 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: url('https://images.unsplash.com/photo-1518837695005-2083093ee35b?q=80&w=2000&auto=format&fit=crop'); /* 默认深蓝海面与星空的底图 */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
/* 水下荧光/花火余辉遮罩层 */
body::after {
    content: ''; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
    background: radial-gradient(circle at 80% 20%, rgba(135, 206, 250, 0.3), transparent 60%),
                radial-gradient(circle at 20% 80%, rgba(255, 158, 170, 0.15), transparent 50%);
    pointer-events: none; z-index: 9999; mix-blend-mode: overlay;
}

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-blue); font-weight: normal; letter-spacing: 2px; }

/* --- 4. 顶部导航栏 & 抽屉背景 --- */
#top-settings-holder { position:relative; background-color: rgba(240, 248, 255, 0.4); backdrop-filter: blur(12px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 32px; height: 32px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.5s cubic-bezier(0.25, 0.8, 0.25, 1); }
.drawer-icon.fa-fw:hover { transform: translateY(-3px) scale(1.1); filter: drop-shadow(0 0 5px rgba(135, 206, 250, 0.8)); }

/* 指定的导航栏贴图替换 */
.drawer-icon.fa-sliders, #ai-config-button .drawer-icon, .drawer-icon.fa-font, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-user, #user-settings-button .drawer-icon, .drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon, .drawer-icon.fa-face-smile, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/EDt4/1167X1518/2026-04-29_225326.png/webp'); 
}
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon, .drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-address-card, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/RVXd/1654X1347/2026-02-27_110430.png/webp'); 
}

/* 抽屉与弹窗背景图替换 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(240, 248, 255, 0.85), rgba(240, 248, 255, 0.95)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/onrl/675X1200/b4bd9888ba0650cffc874cfbd9cb701e.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 16px !important; color: var(--text-main) !important;
    backdrop-filter: blur(10px) !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 25px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { 
    pointer-events: auto; width: 85% !important; max-width: 800px !important; margin: 0 auto !important; 
    background-color: rgba(255, 255, 255, 0.5) !important; padding: 12px 25px !important; 
    backdrop-filter: blur(15px) !important; -webkit-backdrop-filter: blur(15px) !important; 
    border-radius: 40px !important; 
    transition: all 0.5s ease !important; position: relative;
    animation: gentle-water-float 5s ease-in-out infinite;
}
@keyframes gentle-water-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }

#rightSendForm, #leftSendForm { gap: 15px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; line-height: 1.6; }

/* 输入框日文伪提示词 - 忧郁恋爱风 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: '「水面に揺れる想いを綴る...」 🎐'; 
    color: var(--accent-blue); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); 
    font-family: var(--font-japanese); font-size: 0.5em; pointer-events: none; z-index: 10; white-space: nowrap; 
    opacity: 0.7; animation: pulse-glow 4s infinite alternate; letter-spacing: 2px;
}
@keyframes pulse-glow { 0% { opacity: 0.4; filter: blur(0.5px); } 100% { opacity: 0.9; text-shadow: 0 0 8px rgba(135, 206, 250, 0.6); } }

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 36px; height: 36px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); font-size: 0; background-color: transparent; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.15) translateY(-3px); }

/* 底部贴图替换 */
#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/7NjD/957X1673/2026-04-29_225209.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/7NjD/957X1673/2026-04-29_225209.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/kGX2/1238X1327/2026-04-29_225221.png/webp'); }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/7NjD/957X1673/2026-04-29_225209.png/webp'); filter: hue-rotate(180deg) brightness(1.2); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/7NjD/957X1673/2026-04-29_225209.png/webp'); filter: hue-rotate(270deg); }

/* --- 6. 核心：溺于蓝消息框 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 80px auto 40px !important; 
    width: 90%; max-width: 800px; 
    background-color: var(--card-bg) !important;
    border-radius: 12px !important; 
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    overflow: visible !important;
    position: relative; z-index: 10;
    transition: background-color 0.4s ease;
}
.mes:hover { background-color: rgba(255, 255, 255, 0.85) !important; }

/* 消息框顶部独立 GIF 动图横幅区 */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; height: 160px !important; min-height: 160px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-top-left-radius: 12px; border-top-right-radius: 12px;
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/j814/1024X512/tHDHFjEu_converted.gif/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/jO0A/1024X512/WVOgOkEG_converted.gif/webp'); }

/* 悬浮头像框 (增加微微发光的呼吸感) */
.mes .avatar {
    position: absolute;
    top: -45px; 
    width: 90px; height: 90px; 
    background: rgba(255, 255, 255, 0.9) !important; 
    padding: 4px !important; 
    z-index: 30; display: flex !important; align-items: center; justify-content: center;
    border-radius: 50% !important; 
    animation: avatar-breathe 4s infinite alternate;
}
@keyframes avatar-breathe { 0% { box-shadow: 0 0 0 rgba(255,255,255,0); } 100% { box-shadow: 0 0 20px rgba(135, 206, 250, 0.5); } }

.mes[is_user="false"] .avatar { left: 30px; }
.mes[is_user="true"] .avatar { right: 30px; left: auto; }
.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 50% !important; 
}

/* 消息主体区 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 35px 40px 45px 40px !important; position: relative; border: none !important; overflow: visible !important; min-height: 100px !important; z-index: 10; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; position: relative; z-index: 2; }

/* 日系垂直排版文字点缀（代替原来的贴纸） */
.mes_block::before {
    writing-mode: vertical-rl;
    position: absolute; bottom: 35px; opacity: 0.15;
    font-family: var(--font-japanese); font-size: 32px; letter-spacing: 12px;
    color: var(--accent-blue); pointer-events: none; z-index: 1;
}
.mes[is_user="false"] .mes_block::before { content: '青に溺れる'; right: 15px; }
.mes[is_user="true"] .mes_block::before { content: '夜空と花火'; left: 15px; }

/* 思维链自定义 - 深海寻找记忆 */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🫧 思考の深海に潜る... (Thinking)"; 
    font-family: var(--font-japanese); font-size: 16px !important; 
    color: var(--accent-blue); visibility: visible; letter-spacing: 1px; opacity: 0.8;
}
.mes_reasoning { 
    padding-left: 20px !important; margin-bottom: 25px !important; 
    color: var(--text-subtle); font-family: var(--font-quote); font-size: 0.95em; position: relative; 
}
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; 
    background: linear-gradient(to bottom, rgba(74, 144, 226, 0.6), transparent);
    border-radius: 3px;
}
.mes .mes_text { line-height: 2.2; color: var(--text-main); font-size: 15px; text-align: justify; letter-spacing: 0.5px; }

/* --- 楼层信息、名字、按钮与时间戳 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }
.mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    top: -65px !important; 
    left: 0; right: 0; width: 100% !important; 
    align-items: center !important; background: transparent !important; 
    z-index: 100; padding: 0 45px; 
}
.mes[is_user="false"] .ch_name { justify-content: flex-end !important; }
.mes[is_user="true"] .ch_name { justify-content: flex-start !important; }
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; }
.mes .ch_name .name_text { 
    font-family: var(--font-english); font-size: 28px !important; 
    color: #fff !important; text-shadow: 0 2px 5px rgba(0,0,0,0.4), 0 0 10px rgba(135, 206, 250, 0.5); 
}

.mes .mesIDDisplay, .mes .mes_timer { position: static !important; color: var(--text-subtle) !important; font-size: 13px !important; font-family: var(--font-japanese); opacity: 0.7; }

/* 自定义楼层碎片信息 */
.mesIDDisplay::before { content: '✧ 記憶の欠片 第 '; }
.mesIDDisplay::after { content: ' 葉 ✦'; }

.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 10px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 20px; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { 
    background-color: rgba(240, 248, 255, 0.8) !important; color: var(--accent-blue) !important; 
    padding: 8px !important; border-radius: 50% !important; cursor: pointer; transition: all 0.3s ease; font-size: 13px !important; 
}
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { 
    background-color: var(--accent-blue) !important; color: #fff !important; transform: scale(1.15) rotate(5deg); 
    box-shadow: 0 0 8px rgba(74, 144, 226, 0.4) !important;
}

#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260429/kGX2/1238X1327/2026-04-29_225221.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: gentle-water-float 1.5s infinite ease-in-out; border: none !important; height: 40px !important; width: 40px !important; margin: 10px auto !important; opacity: 0.8; }
#typing_indicator .dot { display: none !important; }

/* --- 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { 
    background: rgba(255, 255, 255, 0.4) !important; border-radius: 10px !important; padding: 12px 18px !important; margin-bottom: 10px !important; color: var(--accent-blue) !important; border-left: 3px solid var(--accent-blue) !important;
}
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(255,255,255,0.6) !important; color: var(--text-main) !important; border-radius: 8px !important; padding: 10px !important; transition: all 0.3s ease; }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: rgba(255,255,255,0.9) !important; box-shadow: 0 0 8px rgba(135, 206, 250, 0.4) !important; }
.menu_button { background-color: rgba(255, 255, 255, 0.4) !important; color: var(--text-subtle) !important; transition: all 0.3s ease; border-radius: 10px !important; }
.menu_button:hover { background-color: var(--accent-blue) !important; color: white !important; letter-spacing: 1px; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-blue) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(240, 248, 255, 0.85); z-index: 0; border-radius: 16px; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-coral) !important; color: #fff !important; }

/* 手机端适配调整 */
@media (max-width: 768px) {
    .mes { margin: 60px auto 30px !important; width: 95%; }
    .mes .avatar { width: 70px; height: 70px; top: -35px; }
    .mes .ch_name .name_text { font-size: 22px !important; }
    .mes .mesAvatarWrapper { height: 120px !important; min-height: 120px !important; }
    .mes .mes_block > .ch_name { top: -50px !important; padding: 0 25px; }
    .mes_block::before { font-size: 24px; bottom: 20px; }
}

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(255,255,255,0.7) !important; color: var(--accent-blue) !important; border-radius: 10px !important; padding: 10px 25px !important; margin: 10px 8px !important; transition: all 0.3s ease !important; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-coral) !important; color: #fff !important; transform: scale(1.05) !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--theme-bg-mid) !important; color: #fff !important; transform: scale(1.05) !important; }
